   rx_flit[n]='0;
   for(int ct=0;ct<9;ct++)begin
    automatic int c=arb_lock[n]?arb_owner[n]:(arb_first[n]+ct)%9;
    for(int p=0;p<4;p++)if(peer(c,p)==n)begin
